function renderLente(){
    var p=$id('tb-lens'); if(!p)return;
    var t={cap:'Vetor capital',reg:'Vetor regulação e diplomacia',cad:'Vetor cadeia de valor'}[vet];
    p.innerHTML='<div class="yr">Lente ativa</div><div class="ti">'+esc(t)+'</div>'+
      '<div class="bd2">'+LENTES[vet]+'</div>';
  }

function renderItem(){
    var p=$id('tb-item'); if(!p)return;
    var f=null; FRENTES.forEach(function(o){if(o.k===frente)f=o;});
    if(!f){p.innerHTML='';return;}
    var vl={cap:'Capital',reg:'Regulação e diplomacia',cad:'Cadeia de valor'}[vet];
    p.innerHTML='<div class="yr">'+esc(vl)+' · '+esc(f.n)+'</div>'+
      '<div class="ti">'+esc(f.n)+' pelo vetor '+esc(vl.toLowerCase())+'</div>'+
      '<div class="bd2">'+f[vet]+'</div>'+
      '<div class="lg"><b>Pergunta de verificação</b>'+
      (vet==='cap'?'Qual é a moeda, a condicionalidade, o horizonte e a governança que acompanham esse capital?':
       vet==='reg'?'Isso é lei em vigor, lei sem regulamento, projeto em tramitação, ou compromisso sem força vinculante? E com que data?':
       'O Brasil está na etapa de recurso ou na etapa de transformação? E onde exatamente está o gargalo que impede o salto?')+
      '</div>';
  }

function upd(){
    var el=numOf($id('sg-el'),86.8,0,100);
    var pe=numOf($id('sg-pe'),19,1,100);
    var ne=numOf($id('sg-ne'),41,0,100);
    var of=numOf($id('sg-of'),50,0,100);
    var w=pe/100;
    var ag=w*el+(1-w)*ne;
    var di=el-ag;
    var de=ag-of;
    var co=w*el;
    $id('sg-ag').innerHTML=fmt(ag,1)+'<span class="u">%</span>';
    $id('sg-di').innerHTML=(di>=0?'+':'−')+fmt(Math.abs(di),1)+'<span class="u">p.p.</span>';
    $id('sg-de').textContent=(de>=0?'+':'−')+fmt(Math.abs(de),1)+' p.p. contra o oficial';
    $id('sg-co').textContent=fmt(co,1)+' p.p. dos '+fmt(ag,1)+' agregados';
    $id('sg-b1').style.width=clamp(el,0,100)+'%';
    $id('sg-b2').style.width=clamp(ag,0,100)+'%';
    $id('sg-b3').style.width=clamp(ne,0,100)+'%';
    $id('sg-v1').textContent=fmt(el,1)+'%';
    $id('sg-v2').textContent=fmt(ag,1)+'%';
    $id('sg-v3').textContent=fmt(ne,1)+'%';
    var ad=Math.abs(de), vd=$id('sg-vd'), cls, txt;
    if(ad<=2){cls='ok';txt='<b>Consistente.</b> A renovabilidade agregada implícita fica dentro de dois pontos percentuais do valor oficial que você informou. Isso significa que os três parâmetros de entrada descrevem a mesma economia que a estatística oficial descreve — e que a diferença de '+fmt(Math.abs(di),1)+' pontos entre matriz elétrica e matriz energética é real, não artefato de conta. É essa distância que precisa ser dita sempre que um percentual de renovabilidade for citado.';}
    else if(ad<=6){cls='att';txt='<b>Divergência moderada.</b> A agregada implícita está a '+fmt(ad,1)+' pontos do valor oficial informado. Antes de concluir qualquer coisa, verifique a fronteira contábil do peso da eletricidade: consumo final de eletricidade contra oferta interna de energia dá um número; oferta interna de energia elétrica contra oferta interna de energia total dá outro, porque a segunda inclui as perdas de transformação. Divergência dessa ordem quase sempre é escolha de fronteira, não erro de dado.';}
    else {cls='per';txt='<b>Divergência alta.</b> A agregada implícita está a '+fmt(ad,1)+' pontos do valor oficial. Nessa faixa não se trata mais de fronteira contábil: pelo menos um dos três parâmetros não pertence à mesma base estatística dos outros — ano-base diferente, país diferente, ou grandeza trocada. A conduta correta não é ajustar o parâmetro até fechar: é <b>voltar à fonte de cada um dos três</b> e conferir ano-base e denominador antes de usar qualquer resultado.';}
    vd.className='verdict '+cls; vd.innerHTML=txt;
  }

function render(k){
    var o=null; N.forEach(function(x){if(x.k===k)o=x;});
    var out=$id('vf-out'); if(!out||!o)return;
    out.innerHTML=
      '<div class="ocard"><span class="ok2">Fonte provável</span>'+o.f+'</div>'+
      '<div class="ocard gd2"><span class="ok2">O que a grandeza mede</span>'+o.m+'</div>'+
      '<div class="ocard rd2"><span class="ok2">Erro típico de citação</span>'+o.e+'</div>'+
      '<div class="ocard gr2"><span class="ok2">O que verificar antes de repetir</span>'+o.v+'</div>';
  }

function render(){
    var p=$id('rg-panel'); if(!p)return;
    var m=M[idx];
    p.innerHTML='<div class="yr">'+esc(m.y)+' · marco '+(idx+1)+' de '+M.length+'</div>'+
      '<div class="ti">'+esc(m.n)+'</div>'+
      '<div class="bd2"><b>O que é.</b> '+m.o+'</div>'+
      '<div class="bd2"><b>Estado em 2 de agosto de 2026.</b> '+m.e+'</div>'+
      '<div class="lg"><b>O que ainda falta</b>'+m.f+'</div>';
    var w=$id('rg-grid');
    if(w){$all('button',w).forEach(function(b,i){if(i===idx){b.classList.add('on');}else{b.classList.remove('on');}});}
  }

function upd(){
    var p=segVal('cb-par','data-p')||'china';
    var v=segVal('cb-vet','data-v')||'cap';
    var d=C[p][v], nm=C[p].n;
    var vl={cap:'Capital',reg:'Regulação e diplomacia',cad:'Cadeia de valor'}[v];
    var out=$id('cb-out');
    out.innerHTML=
      '<div class="ocard"><span class="ok2">Estrutura principal</span>'+d.a+'</div>'+
      '<div class="ocard gd2"><span class="ok2">Segundo elemento</span>'+d.b+'</div>'+
      '<div class="ocard rd2"><span class="ok2">Fricção ou ressalva</span>'+d.c+'</div>'+
      '<div class="ocard gr2"><span class="ok2">Leitura operacional</span>'+d.d+'</div>';
    var vd=$id('cb-vd');
    vd.className='verdict att';
    vd.innerHTML='<b>'+esc(nm)+' pelo vetor '+esc(vl.toLowerCase())+'.</b> Troque o vetor mantendo o parceiro e observe que a leitura muda inteiramente. Nenhum parceiro é melhor em abstrato: a avaliação depende do vetor pelo qual se pergunta e do interesse de quem faz a pergunta — e dizer isso, numa conversa, é mais informativo do que qualquer ranking.';
  }

function upd(){
    var i=segVal('rt-inst','data-i')||'emerg';
    var p=segVal('rt-prod','data-p')||'energia';
    var d=I[i], q=P[p];
    $id('rt-aut').textContent=d.aut;
    $id('rt-pra').textContent=d.pra;
    $id('rt-jud').textContent=d.jud;
    $id('rt-rev').textContent=d.rev;
    var vd=$id('rt-vd');
    var exposto=/Exposto/.test(q[i]);
    var isento=/Isentad|Isentado/.test(q[i]);
    vd.className='verdict '+(exposto?'per':(isento?'ok':'att'));
    vd.innerHTML='<b>'+esc(q.n)+' sob '+esc(d.n.toLowerCase())+'.</b> '+q[i]+
      ' <br><br>Antes de repetir qualquer alíquota: a incidência é definida por <b>código tarifário</b>, produto a produto, e a sobretaxa se <b>soma</b> à tarifa regular já aplicável. Um produto com 5% de tarifa regular sob uma sobretaxa de 25% passa a pagar 30%, não 25%.';
    var nt=$id('rt-nota');
    nt.innerHTML='<div class="yr">Instrumento</div><div class="ti">'+esc(d.n)+'</div><div class="bd2">'+d.nota+'</div>';
  }

function upd(){
    var f=segVal('pc-fr','data-f')||'corp';
    var v=segVal('pc-vr','data-v')||'nao';
    var p=segVal('pc-pr','data-p')||'nao';
    var c=segVal('pc-cd','data-c')||'nao';
    var sf=FR[f].s, sv=VR[v].s, sp=PR[p].s, sc=CD[c].s;
    var base=sf+sv+sp;
    var pos, cls, txt;
    if(sf===0){pos='Não atribuível a produto';}
    else if(base>=5){pos='Defensável';}
    else if(base>=3){pos='Parcial';}
    else {pos='Frágil';}
    var blq;
    if(sf===0){blq='Fronteira do inventário';}
    else if(sv===0){blq='Ausência de verificação';}
    else if(sp===0){blq='Ausência de dado de precursor';}
    else if(sv===1){blq='Verificação apenas interna';}
    else if(sp===1){blq='Cobertura parcial de precursor';}
    else if(sf===1){blq='Fronteira pode ser insuficiente para o produto';}
    else {blq='Nenhum eixo bloqueia o dado';}
    var vpd;
    if(sf===0||sp===0){vpd='Alto — valor padrão provável';}
    else if(sv===0){vpd='Alto — dado sem verificação';}
    else if(base>=5){vpd='Baixo';}
    else {vpd='Moderado';}
    var des;
    if(sc===0){des='Indisponível — sem regime no país';}
    else if(sc===1){des='Indisponível hoje, previsível no futuro';}
    else {des='Potencialmente aplicável, sujeito a reconhecimento';}
    $id('pc-pos').textContent=pos;
    $id('pc-blq').textContent=blq;
    $id('pc-vpd').textContent=vpd;
    $id('pc-des').textContent=des;
    if(sf===0){
      cls='per';
      txt='<b>Bloqueio na fronteira, e nenhum outro eixo compensa.</b> '+FR[f].d+' Enquanto o inventário for corporativo, verificação por terceiro e dado de precursor não resolvem — porque não há a quem atribuir a emissão. O primeiro movimento, e o único que importa neste estado, é construir inventário <b>por produto</b>. Todo o resto vem depois.';
    } else if(base>=5){
      cls='ok';
      txt='<b>Posição defensável.</b> Fronteira de produto declarada, verificação e dado de precursor em nível que sustenta negociação com comprador exigente. Neste estado, a vantagem da eletricidade brasileira de baixo fator de emissão pode ser efetivamente demonstrada, em vez de apenas afirmada. Duas ressalvas permanecem: emissões de processo e de combustível térmico não são compensadas pela matriz elétrica, e a metodologia aplicável é a do mecanismo, não a do inventário corporativo.';
    } else if(base>=3){
      cls='att';
      txt='<b>Posição parcial.</b> O dado existe e é atribuível a produto, mas o eixo que bloqueia — '+esc(blq.toLowerCase())+' — é o que o comprador vai apontar primeiro. Em negociação, dado não verificado ou com precursor incompleto tende a ser tratado como não existente, e o resultado prático é o mesmo de não ter dado: aplicação de valor padrão. O investimento de maior retorno aqui não é redução de emissão, é <b>fechamento do eixo que falta</b>.';
    } else {
      cls='per';
      txt='<b>Posição frágil.</b> A fronteira é de produto, o que é o passo mais difícil e já foi dado, mas verificação e dado de precursor estão em nível que não sustenta comprovação perante terceiro. Sem eles, o inventário é declaração unilateral. A sequência de menor custo é fechar precursor dos principais fornecedores primeiro e verificação por terceiro depois — nessa ordem, porque verificar um inventário sem dado de precursor apenas certifica a lacuna.';
    }
    if(sc===2 && sf>0){
      txt+=' <br><br><b>Sobre o desconto de carbono doméstico:</b> com regime operacional e reconhecido, o preço de carbono já pago no país pode ser considerado — o que depende de reconhecimento formal e de comprovação de pagamento, não da simples existência da lei.';
    } else if(sc===1){
      txt+=' <br><br><b>Sobre o desconto de carbono doméstico:</b> um regime em regulamentação não produz desconto. É a situação brasileira na data de verificação — lei de dezembro de 2024, regulamentação infralegal em construção, mercado regulado previsto para o início da década de 2030.';
    }
    var vd=$id('pc-vd'); vd.className='verdict '+cls; vd.innerHTML=txt;
  }

function upd(){
    var pts=0, vin=0, blq=[];
    IT.forEach(function(o){
      var v=st[o.k]; pts+=v;
      if(v===2)vin++;
      if(o.crit&&v===0)blq.push(o.n);
    });
    var est;
    if(pts<=3)est='Anúncio';
    else if(pts<=7)est='Estudo';
    else if(pts<=11)est='Desenvolvimento';
    else if(pts<=15)est='Estruturação avançada';
    else est='Pronto para implantação';
    $id('mp-pts').innerHTML=pts+'<span class="u">/ 18</span>';
    $id('mp-est').textContent=est;
    $id('mp-vin').textContent=vin+' de 9';
    $id('mp-blq').textContent=blq.length===0?'nenhum':(blq.length+' de 3');
    var vd=$id('mp-vd'), cls, txt;
    if(blq.length===3){
      cls='per';
      txt='<b>Os três itens críticos estão ausentes.</b> Independentemente da pontuação total, este é um anúncio. Energia, comprador e capital são o que converte intenção em projeto, e nenhum avanço em licenciamento, engenharia ou terreno substitui os três. Um projeto neste estado pode ser real, sério e bem conduzido — mas não pertence à mesma tabela de um projeto contratado, e somar os dois produz um número que não significa nada.';
    } else if(blq.length>0){
      cls='per';
      txt='<b>Bloqueio crítico: '+esc(blq.join('; '))+'.</b> A pontuação de '+pts+' pode sugerir maturidade, e é exatamente aí que a soma engana. '+(pts>=12?'Com '+pts+' pontos, este projeto aparece como avançado em qualquer tabela agregada, e ainda assim falta o item que decide se ele existe. ':'')+'Antes de qualquer discussão sobre prazo de entrega ou capacidade instalada, a pergunta é o que falta para destravar esse item específico — e se o que falta está sob controle do proponente ou depende de terceiro.';
    } else if(pts>=16){
      cls='ok';
      txt='<b>Pronto para implantação, com os três críticos atendidos.</b> Este é o único estado em que a capacidade anunciada pode ser somada a outras da mesma categoria sem produzir distorção. Duas ressalvas de método permanecem: a régua mede evidência documental, não execução — projetos com decisão final de investimento atrasam, encarecem e ocasionalmente são cancelados; e "pronto" não é "em operação", que é uma categoria distinta e verificável separadamente.';
    } else if(pts>=12){
      cls='att';
      txt='<b>Estruturação avançada, sem bloqueio crítico.</b> Os três itens que decidem estão pelo menos indicativos, e o que falta é conversão de indicativo em vinculante. Neste estágio, a pergunta útil não é sobre o projeto e sim sobre a <b>sequência</b>: qual item precisa fechar primeiro para que os demais possam fechar, e qual deles depende de ato de terceiro — regulador, financiador ou comprador — em vez de depender do proponente.';
    } else if(pts>=8){
      cls='att';
      txt='<b>Desenvolvimento.</b> Há trabalho real e verificável, e nenhum crítico em zero. Ainda assim, indicativo não é vinculante: memorando, carta de interesse e termo indicativo são documentos que registram intenção e não obrigam a nada. Ao ler um comunicado sobre um projeto neste estágio, o teste de uma linha é procurar a palavra que descreve o vínculo — e, na ausência dela, presumir que não existe.';
    } else if(pts>=4){
      cls='per';
      txt='<b>Estudo.</b> O projeto tem substância técnica e nenhum compromisso firmado. É um estágio legítimo e necessário — todo projeto passa por ele —, mas a distância até a operação continua sendo medida em anos e em decisões que ainda não foram tomadas. Capacidade nesse estágio não deve entrar em nenhuma soma apresentada como potencial do país.';
    } else {
      cls='per';
      txt='<b>Anúncio.</b> Nada aqui é vinculante. Note que este é o estado da maior parte da capacidade que aparece em manchetes sobre hidrogênio no Brasil e no mundo, e que somar essas capacidades produz um total impressionante e analiticamente vazio. A formulação honesta para descrever este conjunto é <b>potencial de implementação</b>, com o horizonte declarado — que foi, aliás, a formulação adotada pela própria chamada pública brasileira de polos.';
    }
    vd.className='verdict '+cls; vd.innerHTML=txt;
    var alvo=null;
    for(var i=0;i<IT.length;i++){ if(IT[i].crit && st[IT[i].k]<2 && IT[i].nota){ alvo=IT[i]; break; } }
    if(!alvo){ for(var j=0;j<IT.length;j++){ if(st[IT[j].k]<2 && IT[j].nota){ alvo=IT[j]; break; } } }
    if(!alvo){ alvo=IT[8]; }
    var red=$id('mp-red');
    red.innerHTML='<div class="yr">Item em foco · estado '+st[alvo.k]+' de 2</div>'+
      '<div class="ti">'+esc(alvo.n)+'</div><div class="bd2">'+alvo.nota+'</div>';
  }

function pc(v){
    if(!isFinite(v))return '—';
    if(v===0)return '0%';
    if(v<0.01)return v.toFixed(4).replace('.',',')+'%';
    if(v<1)return v.toFixed(3).replace('.',',')+'%';
    return v.toFixed(1).replace('.',',')+'%';
  }

function upd(){
    var rn=numOf($id('rp-rn'),21,0.1,200);
    var rm=numOf($id('rp-rm'),85,1,500);
    var pn=numOf($id('rp-pn'),0.02,0,500);
    var pm=numOf($id('rp-pm'),390,1,5000);
    var sr=rn/rm*100;
    var sp=pn/pm*100;
    var incons=(rn>rm)||(pn>pm);
    var ra=(sp>0)?(sr/sp):Infinity;
    var anos=(pn>0)?(rn*1000/pn):Infinity;
    $id('rp-pr').textContent=pc(sr);
    $id('rp-pp').textContent=pc(sp);
    $id('rp-ra').textContent=(sp>0)?(ra>=100?fmt(Math.round(ra),0)+'×':ra.toFixed(1).replace('.',',')+'×'):'indefinida';
    $id('rp-an').textContent=(pn>0)?fmt(Math.round(anos),0):'indefinido';
    var w1=Math.max(0.5,Math.min(100,sr)), w2=Math.max(0.5,Math.min(100,sp));
    $id('rp-b1').style.width=w1+'%'; $id('rp-b2').style.width=w2+'%';
    $id('rp-v1').textContent=pc(sr); $id('rp-v2').textContent=pc(sp);
    var vd=$id('rp-vd'), cls, txt;
    if(incons){
      cls='per';
      txt='<b>Entrada inconsistente.</b> '+(rn>rm?'A reserva nacional informada é maior que a reserva mundial. ':'')+(pn>pm?'A produção nacional informada é maior que a produção mundial. ':'')+'O instrumento não corrige a entrada porque o objetivo é justamente esse: quando duas fontes diferentes são combinadas sem checagem de coerência, a aritmética continua funcionando e o resultado continua parecendo um número. Confira se os dois valores vêm da mesma metodologia e do mesmo ano-base antes de dividir um pelo outro.';
    } else if(pn===0){
      cls='per';
      txt='<b>Produção nacional nula: a assimetria é máxima e a razão é indefinida.</b> Este é o caso-limite que o módulo existe para nomear. Um país pode deter parcela relevante da reserva mundial de um mineral e produzir zero, e nessa situação a reserva não confere nenhuma posição de barganha — confere apenas a <b>possibilidade</b> de construir uma, ao custo e no prazo de uma cadeia industrial que ainda não existe. Reserva no subsolo não é oferta no mercado.';
    } else if(ra>=100){
      cls='per';
      txt='<b>Assimetria extrema: participação na reserva '+esc((ra>=1000?fmt(Math.round(ra),0):ra.toFixed(0)))+' vezes maior que na produção.</b> Este é aproximadamente o caso brasileiro em terras-raras nos valores de referência: parcela expressiva da reserva mundial e produção de ordem de grandeza desprezível. A leitura correta não é "o Brasil é uma potência mineral" nem "o Brasil não tem nada" — é que o país tem <b>dotação sem cadeia</b>. E o gargalo, na maioria dos minerais críticos, não está na mina: está na separação, no refino e na manufatura do componente final, etapas que exigem capital, escala, tecnologia e demanda contratada.';
    } else if(ra>=5){
      cls='att';
      txt='<b>Assimetria alta.</b> A participação na reserva excede a participação na produção por fator de '+ra.toFixed(1).replace('.',',')+'. Há produção real, mas muito abaixo do que a dotação permitiria. Neste intervalo, a pergunta de política pública deixa de ser "como começar" e passa a ser "o que limita a expansão" — e as respostas típicas são licenciamento, infraestrutura de escoamento, capital e ausência de comprador de longo prazo, não ausência de recurso.';
    } else if(ra>=1.5){
      cls='att';
      txt='<b>Assimetria moderada.</b> Fator de '+ra.toFixed(1).replace('.',',')+' entre reserva e produção. O país produz aquém da sua dotação, mas está no jogo. Neste intervalo, participação de mercado passa a ser objeto de negociação comercial e não apenas de política industrial, e a posição de barganha começa a existir de fato.';
    } else if(ra>=0.8){
      cls='ok';
      txt='<b>Participações proporcionais.</b> A parcela na produção corresponde aproximadamente à parcela na reserva. É a situação do Brasil em minério de ferro e, em outra ordem de grandeza, em nióbio — dotação convertida em cadeia. Vale notar que mesmo aqui a pergunta de valor agregado permanece aberta: produzir na proporção da reserva não significa capturar a etapa de maior margem.';
    } else {
      cls='att';
      txt='<b>Produção acima da parcela na reserva.</b> Fator de '+ra.toFixed(2).replace('.',',')+'. O país extrai proporcionalmente mais do que detém, o que pode indicar cadeia madura, custo competitivo ou depleção mais rápida do estoque conhecido. As três hipóteses exigem verificação separada, e nenhuma delas se resolve por esta razão isoladamente.';
    }
    if(pn>0){
      txt+=' <br><br><b>Sobre "anos de reserva ao ritmo atual":</b> '+fmt(Math.round(anos),0)+' anos é uma razão entre estoque e fluxo, não uma previsão. Números na casa das centenas de milhares não descrevem abundância eterna — descrevem produção quase nula em relação ao estoque, que é exatamente o mesmo fato que a razão de assimetria já mostrou, expresso em outra unidade.';
    }
    vd.className='verdict '+cls; vd.innerHTML=txt;
  }

function upd(k){
    var e=null; E.forEach(function(o){if(o.k===k)e=o;});
    if(!e)e=E[0];
    var c=CAT[e.cat];
    $id('cn-out').innerHTML=
      '<div class="ocard"><span class="ok2">Classificação</span><b>'+esc(c.n)+'</b></div>'+
      '<div class="ocard gd2"><span class="ok2">Onde pode aparecer</span>'+esc(e.ond)+'</div>'+
      '<div class="ocard gr2"><span class="ok2">Substituição correta</span>'+e.sub+'</div>';
    var vd=$id('cn-vd');
    vd.className='verdict '+c.cls;
    vd.innerHTML='<b>'+esc(c.st)+'.</b> '+e.por;
  }

function render(){
    var m=M[i];
    $id('ad-bd').innerHTML=
      '<div class="and-clock">Minuto '+esc(m.t)+' · movimento '+(i+1)+' de 8</div>'+
      '<div class="and-q">'+esc(m.q)+'</div>'+
      '<div class="and-sec"><div class="sk">Âncoras</div><ul class="and-anc">'+
